from pathlib import Path
import json,hashlib,datetime,zipfile
import numpy as np
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'artifacts/analog_asic'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def rel(p):return p.relative_to(ROOT).as_posix()
def main():
 old=BASE/'assembly/article_module_catalog_v8.json';cat=json.loads(old.read_text());assert all(sha(ROOT/n)==h for n,h in cat['sha256'].items());script=ROOT/'scripts/screen_gf180_sequenced_signed_injector_prebiased_complete_bounded.py';h=sha(script)[:12];rps=[BASE/'results'/f'gf180_sequenced_signed_injector_v2_prebiased_complete_case{i}_src{h}.json' for i in range(3)];reports=[json.loads(p.read_text()) for p in rps];assert all(r['module_simulation_completed'] for r in reports)
 cases=[r['cases'][0] for r in reports];margins=[]
 for rp,r,c in zip(rps,reports,cases):
  for n,digest in r['sha256'].items():
   p=ROOT/n
   if p.suffix!='.ext':assert sha(p)==digest,n
  dp=rp.with_suffix('.dat');w=np.loadtxt(dp,skiprows=1);t=w[:,0];y=w[:,7];idx=np.where((y[:-1]>=1.65)&(y[1:]<1.65)&(t[:-1]>1079e-6)&(t[:-1]<1095e-6))[0];assert len(idx)==1;i=int(idx[0]);armfall=t[i]+(1.65-y[i])*(t[i+1]-t[i])/(y[i+1]-y[i]);margins.append(None if len(c['falling_edges_s'])!=1 else float((armfall-c['falling_edges_s'][0])*1e6))
 usable=bool(all(r['expected_sign_observed'] for r in reports) and all(c['ready_end_v']>2.9 and c['ready_during_arm_v']<.4 and all(n==1 for n in c['sequencer_strobe_counts'].values()) and c['pulse_width_us'] is not None for c in cases) and all(m is not None and m>0 for m in margins) and cases[1]['net_charge_into_state_c']>cases[0]['net_charge_into_state_c'] and cases[1]['pulse_width_us']>cases[0]['pulse_width_us'])
 cell='gf180_sequenced_signed_injector_v2';entry=next(e for e in cat['characterization_assemblies'] if e['cell']==cell);entry['limitations']=reports[0]['scope'];entry['three_prebiased_local_event_cases_usable']=usable
 for rp in rps:entry['views'][rp.name]=rel(rp);cat['sha256'][rel(rp)]=sha(rp)
 cat['revision']=9;cat['previous_catalog']=rel(old);cat['next_assembly']='Complete bin/DAG completion and commit controls, shared references, adaptation/inhibition/readout, then compact dense/full executed hierarchy. Preserve1ms global prebias requirement and signed magnitude asymmetry; original-float accuracy and population5ms remain unaccepted.'
 cp=BASE/'assembly/article_module_catalog_v9.json';assert not cp.exists();cp.write_text(json.dumps(cat,indent=2)+'\n')
 audit={'catalog':rel(cp),'module_artifact_sets':len(cat['modules']),'characterization_assemblies':len(cat['characterization_assemblies']),'fixed_global_prebias_us':1000,'local_clock_hz':50000,'cases':cases,'pulse_completion_margin_before_ARM_fall_us':margins,'three_prebiased_local_event_cases_usable':usable,'scope':'Only nominal local request-to-charge path after fixed power-on initialization. Native sequencer/guard/ramp/sign gates/injector and interconnect real. External analog programming,bias,PARK,state reset interface and clock/reset/request remain. Three standalone events, not repeated service, bin/DAG completion, accuracy or full-chip acceptance. Source imbalance and calibration unfinished.','original_float_accuracy_accepted':False,'full_5ms_population_service_accepted':False,'full_chip_layout_complete':False,'sha256':{rel(p):sha(p) for p in [old,cp,script,Path(__file__),*rps]}}
 ap=BASE/'results/gf180_prebiased_autonomous_event_boundary.json';assert not ap.exists();ap.write_text(json.dumps(audit,indent=2)+'\n')
 docs=[ROOT/'docs'/n for n in ['AGENTS.md','ACTIVE_TASKS.md','ARCHITECTURE.md','DECISIONS.md','RESULTS.md','PROGRESS.md','project_spec.yaml']];stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ');zp=BASE/'documentation_history'/('project_docs_before_prebiased_event_result_'+stamp+'.zip')
 with zipfile.ZipFile(zp,'x',zipfile.ZIP_DEFLATED) as z:
  for p in docs:z.writestr(rel(p),p.read_bytes())
 zp.with_suffix('.json').write_text(json.dumps({'archive_sha256':sha(zp),'files':{rel(p):{'bytes':p.stat().st_size,'sha256':sha(p)} for p in docs}},indent=2)+'\n',encoding='utf-8')
 steps='/'.join(f"{c['state_step_v']*1000:+.3f}" for c in cases);widths='/'.join('none' if c['pulse_width_us'] is None else f"{c['pulse_width_us']:.3f}" for c in cases)
 def insert(name,section):
  p=ROOT/'docs'/name;raw=p.read_bytes();i=raw.index(b'\n## ');tmp=p.with_suffix('.tmp');tmp.write_bytes(raw[:i]+section.encode('utf-8')+raw[i:]);tmp.replace(p)
 insert('RESULTS.md',f'''\n## Complete prebiased local request-to-charge results - 2026-10-10\n\n[Prebiased event boundary](../{rel(ap)}) and [catalog revision9](../{rel(cp)}) retain12 modules/8 characterization assemblies. Same230MOS4MIM physical parent; fixed1ms prebias,50kHz clock and common analog biases. Three complete small-positive/large-positive/large-negative events give pulse widths{widths}us and state steps{steps}mV. All-case local usability check:{usable}; it checks charge signs, positive magnitude ordering, one pulse and one of each sequencer strobe, pulse finishing beforeARM ends, READY low duringARM and high afterDONE. Raw completion margins and waveforms retained.\n\nThis resolves the short-startup ARM-clipping diagnosis only at these three nominal points. It does not establish float-weight calibration, mismatch/noise, repeat-event service, full-population5ms, bin completion or complete neuron behavior. Shared references/programming, bin/DAG commit, adaptation/inhibition/readout, dense/full layout and original-float accuracy still required.\n''')
 p=ROOT/'docs/ACTIVE_TASKS.md';raw=p.read_bytes().replace(b'article_module_catalog_v8.json',b'article_module_catalog_v9.json').replace(b'catalog revision8',b'catalog revision9');a=raw.index(b'| Job status |');b=raw.index(b'\n',a);raw=raw[:a]+f'| Job status | Three complete prebiased local event cases finished; widths{widths}us, state steps{steps}mV; local usability={usable}; no live simulator |'.encode()+raw[b:];raw=raw.replace(b'the joined injector pulse clips toARM and is under internal cutoff diagnosis',b'fixed1ms prebias restores joined cutoff in complete nominal cases');p.write_bytes(raw)
 insert('PROGRESS.md',f'\nComplete local event milestone: three prebiased request-toDONE/READY cases finish with widths{widths}us and steps{steps}mV. Local usability={usable}. Catalog revision9,12 modules/8 assemblies. Full goal remains incomplete. Exact pre-update docs: `{rel(zp)}`.\n')
 p=ROOT/'docs/ARCHITECTURE.md';raw=p.read_bytes().replace(b'Catalog revision8 owns current',b'Catalog revision9 owns current').replace(b'Full prebiased request-toDONE/READY runs remain pending; sustained throughput and repeat-event initialization are not established.',b'Three complete nominal prebiased request-toDONE/READY runs are recorded in catalog revision9; sustained throughput and repeat-event initialization remain unestablished.');p.write_bytes(raw)
 p=ROOT/'docs/project_spec.yaml';raw=p.read_bytes();head,tail=raw.split(b'\ndocument:',1);head=head.replace(b'article_module_catalog_v8.json',b'article_module_catalog_v9.json').replace(b'gf180_autonomous_event_charge_boundary.json',b'gf180_prebiased_autonomous_event_boundary.json').replace(b'  live_sessions: [sequenced_signed_injector_prebiased_complete_cases_sequential_300s_each]',b'  live_sessions: []').replace(b'status: twelve_modules_eight_assemblies_joined_pulse_clipped_cutoff_diagnosis_running',b'status: twelve_modules_eight_assemblies_prebiased_local_event_cases_complete').replace(b'next_action: diagnose_joined_weight_cutoff_then_bin_commit_references_remaining_functions_dense_full_assembly',b'next_action: bin_commit_references_adaptation_inhibition_readout_dense_full_assembly');p.write_bytes(head+b'\ndocument:'+tail)
 print(json.dumps({'catalog':rel(cp),'audit':rel(ap),'widths_us':widths,'steps_mv':steps,'usable':usable,'margins_us':margins},indent=2))
if __name__=='__main__':main()
